package com.massivex.android.transfer

import kotlinx.coroutines.*
import org.junit.Assert.*
import org.junit.Test

class TransferFinalityTest {
    @Test fun twoOfficialConsistentSuccessReadsUnlockOnlyAfterDurableReceipt()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();val before=h.disk.writes;h.coordinator.reconcile(h.record().operationId);assertEquals(2,h.finality.observeCalls);assertEquals(1,h.finality.contextCalls);assertEquals(before+3,h.disk.writes);assertEquals(TransferState.VERIFIED_SUCCESS,h.record().state);assertNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun failedFinalExecutionDistinctFromSuccess()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final(false);h.coordinator.reconcile(h.record().operationId);assertEquals(TransferState.VERIFIED_FAILURE,h.record().state);assertNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun missingPrunedExpiredOrNullNeverUnlocks()=runBlocking{val h=TransferHarness().start();h.send();h.now+=1_000_000;h.coordinator.reconcile(h.record().operationId);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)));assertEquals(TransferState.UNKNOWN,h.record().state);assertNull(h.record().resolution)}
    @Test fun twoPendingReportsRemainPending()=runBlocking{val h=TransferHarness().start();h.send();h.finality.observation={_,_->OperationObservation(TransferState.PENDING)};h.coordinator.reconcile(h.record().operationId);assertEquals(TransferState.PENDING,h.record().state);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun oneTerminalThenMissingCannotUnlock()=runBlocking{val h=TransferHarness().start();h.send();h.finality.observation={s,i->if(i==1)OperationObservation(TransferState.VERIFIED_SUCCESS,report(s,h.now))else OperationObservation(TransferState.UNKNOWN)};h.coordinator.reconcile(h.record().operationId);assertEquals(1,h.record().claims);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)));assertEquals(0,h.finality.contextCalls)}
    @Test fun oppositeTerminalReportsStickAcrossFutureAgreement()=runBlocking{val h=TransferHarness().start();h.send();h.finality.observation={s,i->val ok=i==1;OperationObservation(if(ok)TransferState.VERIFIED_SUCCESS else TransferState.VERIFIED_FAILURE,report(s,h.now,ok))};h.coordinator.reconcile(h.record().operationId);assertEquals(3,h.record().claims);h.finality.final();h.coordinator.reconcile(h.record().operationId);assertEquals(TransferState.UNKNOWN,h.record().state);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun firstReadErrorDoesNotEraseIntent()=runBlocking{val h=TransferHarness().start();h.send();h.finality.observation={_,_->throw java.io.IOException()};h.coordinator.reconcile(h.record().operationId);assertEquals(TransferState.PENDING,h.record().state);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun secondReadErrorRetainsFirstTerminalClaimDurably()=runBlocking{val h=TransferHarness().start();h.send();h.finality.observation={s,i->if(i==1)OperationObservation(TransferState.VERIFIED_SUCCESS,report(s,h.now))else throw java.io.IOException()};h.coordinator.reconcile(h.record().operationId);assertEquals(1,TransferLedger(h.disk).records().single().claims);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun finalStatusRecheckFailureCannotUnlock()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();h.finality.context={throw java.io.IOException()};h.coordinator.reconcile(h.record().operationId);assertEquals(1,h.record().claims);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun terminalEvidenceFromWrongEndpointFails()=runBlocking{val h=TransferHarness().start();h.send();h.finality.observation={s,_->OperationObservation(TransferState.VERIFIED_SUCCESS,report(s,h.now).copy(endpoint="https://untrusted.invalid"))};h.coordinator.reconcile(h.record().operationId);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)));assertEquals(0,h.record().claims)}
    @Test fun reportedWrongChainFails()=runBlocking{val h=TransferHarness().start();h.send();h.finality.observation={s,_->OperationObservation(TransferState.VERIFIED_SUCCESS,report(s,h.now).copy(context=VerifiedNodeContext(1,"MAIN.5.1",h.now)))};h.coordinator.reconcile(h.record().operationId);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun finalContextVersionChangeFails()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();h.finality.context={VerifiedNodeContext(CHAIN,"MAIN.5.0",h.now)};h.coordinator.reconcile(h.record().operationId);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun insufficientReadSeparationFails()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();val c=SendCoordinator(h.reader,h.ledger,h.finality,h.broadcast,{h.now},{ });c.select(TransferSource.capture(h.wallet));c.resume();c.reconcile(h.record().operationId);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)));assertEquals(SendError.EVIDENCE,c.state.value.error)}
    @Test fun staleEndContextFails()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();h.finality.context={val at=h.now;h.now+=20001;VerifiedNodeContext(CHAIN,"MAIN.5.1",at)};h.coordinator.reconcile(h.record().operationId);assertNotNull(h.ledger.pending(TransferSource.capture(h.wallet)))}
    @Test fun publicReadDoesNotNeedSeedOrAuth()=runBlocking{val h=TransferHarness().start();h.send();h.auth.denied=com.massivex.android.wallet.WalletError.AUTH;h.secrets.decryptFailure=com.massivex.android.wallet.WalletError.AUTH;h.finality.final();val n=h.auth.actions.size;h.coordinator.reconcile(h.record().operationId);assertEquals(n,h.auth.actions.size);assertEquals(TransferState.VERIFIED_SUCCESS,h.record().state)}
    @Test fun cancelBetweenObservationsKeepsFirstClaimAndNoSubmission()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();val c=SendCoordinator(h.reader,h.ledger,h.finality,h.broadcast,{h.now},{throw CancellationException("PUBLIC cancel read")});c.select(TransferSource.capture(h.wallet));c.resume();try{c.reconcile(h.record().operationId)}catch(_:CancellationException){};assertEquals(1,TransferLedger(h.disk).records().single().claims);assertEquals(1,(h.broadcast as RecordingTransport).calls)}
    @Test fun noUnknownOperationCanTriggerRead()=runBlocking{val h=TransferHarness().start();h.coordinator.reconcile("not-in-journal");assertEquals(0,h.finality.observeCalls);assertEquals(SendError.EVIDENCE,h.coordinator.state.value.error)}
    @Test fun terminalPersistenceFailureDoesNotReleaseSource()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();h.disk.failWrite=h.disk.writes+3;h.coordinator.reconcile(h.record().operationId);assertEquals(SendError.JOURNAL,h.coordinator.state.value.error);assertNotNull(TransferLedger(h.disk).pending(TransferSource.capture(h.wallet)))}
    @Test fun terminalIdentityAndReceiptSurviveRestart()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();h.coordinator.reconcile(h.record().operationId);val r=TransferLedger(h.disk).records().single();assertEquals(TransferState.VERIFIED_SUCCESS,r.state);r.resolution!!.validate(r.signed);assertEquals(TRUST_POLICY,r.resolution.policy)}
    @Test fun terminalRecordCannotBeReconciledOrDowngraded()=runBlocking{val h=TransferHarness().start();h.send();h.finality.final();h.coordinator.reconcile(h.record().operationId);val n=h.finality.observeCalls;h.coordinator.reconcile(h.record().operationId);assertEquals(n,h.finality.observeCalls);rejects{h.ledger.transition(h.record().operationId,TransferState.UNKNOWN,h.now,TransferNote.RESPONSE_UNKNOWN)}}
    @Test fun differentSourcesRemainIndependentUntilTheirOwnResolution(){val disk=MemoryJournal();val l=TransferLedger(disk);val a=signed();val b=signed(review(seed=44),44);for(s in listOf(a,b))l.acquire(s.draft.source).use{l.prepared(s,TEST_TIME)};val e=resolution(a);listOf(e.first,e.second).forEach{l.observation(a.draft.operationId,OperationObservation(TransferState.VERIFIED_SUCCESS,it),it.observedAt)};l.resolve(a.draft.operationId,e,e.acceptedAt);l.acquire(a.draft.source).close();rejects(SendError.LOCKED){l.acquire(b.draft.source)};assertEquals(2,l.records().size)}
    @Test fun recoveryReturnsToCompletedPresentationOnlyAfterDurableResolution()=kotlinx.coroutines.runBlocking{
        val h=TransferHarness().start();h.send();h.coordinator.stop();h.coordinator.resume();h.coordinator.reload()
        assertEquals(SendPhase.FORM,h.coordinator.state.value.phase);assertNotNull(h.coordinator.state.value.pending)
        h.finality.final();h.coordinator.reconcile(h.record().operationId)
        assertEquals(TransferState.VERIFIED_SUCCESS,TransferLedger(h.disk).records().single().state)
        assertEquals(SendPhase.STATUS,h.coordinator.state.value.phase);assertNull(h.coordinator.state.value.pending)
        assertEquals(1,(h.broadcast as RecordingTransport).calls)
    }

}
